UPDATE public.site_content SET content_value = $json$[{"id":"p07","title":"Explainable AI for Adversarial Intrusion Detection","description":"Undergraduate thesis: Explaining the Attack Surface — XAI-driven defense against adversarial perturbations in deep learning-based intrusion detection. Explored a CNN-BiLSTM detector, FGSM/PGD/C&W attacks through IBM ART, SHAP explanations and an interactive defense visualizer.","technologies":["Python","CNN-BiLSTM","SHAP","IBM ART"],"project_type":"AI/ML","year":"Undergraduate thesis","featured":true,"github_url":"","demo_url":"","image_url":"/projects/p07.svg","impact":[]},{"id":"p13","title":"Elaka360 — Local Information Platform","description":"Bangla-first, mobile-first local-information platform for Bangladesh, in early development. A NestJS REST API over PostgreSQL and a Next.js PWA cover the administrative hierarchy from division to union, with seed data for 64 districts, 495 upazilas and 4,541 unions.","technologies":["Next.js","NestJS","PostgreSQL","TypeScript","Tailwind CSS","Python"],"project_type":"Web Development","year":"2026 · In development","featured":true,"github_url":"https://github.com/sufyan-github/elaka360","demo_url":"","image_url":"/projects/p13.svg","impact":[]},{"id":"p14","title":"KAJ — Local Work & Service Marketplace","description":"Bangla-first local work and service marketplace for a Rajshahi pilot, in early development. A pnpm monorepo with a NestJS API, Prisma on PostgreSQL, Redis and shared TypeScript contracts; a Next.js admin app and a Flutter mobile app are planned.","technologies":["NestJS","Prisma","PostgreSQL","Redis","TypeScript","Docker"],"project_type":"Web Development","year":"2026 · In development","featured":true,"github_url":"https://github.com/sufyan-github/KaJ-App","demo_url":"","image_url":"/projects/p14.svg","impact":[]},{"id":"p15","title":"CareMate — Medication Support App","description":"Medication-support and family-care app for Bangladesh, in development. An Android-first Flutter app with a NestJS API: phone OTP sign-in with rotating refresh tokens, patient profiles, medication records and timezone-aware dose schedules.","technologies":["Flutter","Dart","NestJS","TypeScript","libSQL/Turso"],"project_type":"Mobile Development","year":"2026 · In development","featured":true,"github_url":"https://github.com/sufyan-github/CareMate-App","demo_url":"","image_url":"/projects/p15.svg","impact":[]},{"id":"p16","title":"RUET IoT Club Platform","description":"Web platform for RUET IoT Club with events and registration, courses, verifiable certificates, a blog, member and team pages, and role-based admin and moderator dashboards. Built with React, TypeScript and Supabase.","technologies":["React","TypeScript","Supabase","Tailwind CSS"],"project_type":"Web Development","year":"2026","featured":true,"github_url":"https://github.com/sufyan-github/ruet-iot-club-75338f35","demo_url":"","image_url":"/projects/p16.svg","impact":[]},{"id":"p08","title":"SpotSync — Smart Parking & EV Charging API","description":"Smart parking and EV charging REST API built with Go, Echo v4, GORM and PostgreSQL. Applied STRIDE and DREAD threat modelling in a security coursework case study.","technologies":["Go","Echo v4","GORM","PostgreSQL","STRIDE","DREAD"],"project_type":"Web Development","year":"Academic project","featured":true,"github_url":"","demo_url":"","image_url":"/projects/p08.svg","impact":[]},{"id":"p09","title":"Attendance Management App","description":"Mobile attendance application with course selection, authentication and attendance history.","technologies":["Flutter","Dart","Firebase Auth","Realtime Database","Riverpod"],"project_type":"Mobile Development","year":"2024","featured":true,"github_url":"","demo_url":"","image_url":"/projects/p09.svg","impact":[]},{"id":"p10","title":"Project NEXUS — Water-Quality Monitoring","description":"IoT water-quality monitoring initiative involving sensing, data acquisition and prototype development with RUET IoT Club.","technologies":["IoT","Sensors","Data Acquisition"],"project_type":"IoT","year":"2025","featured":true,"github_url":"","demo_url":"","image_url":"/projects/p10.svg","impact":[]},{"id":"p11","title":"EcoHomeAI — Early-Stage Venture","description":"Founder and technical lead of an early-stage smart-home and energy-management venture, focused on AI, IoT and prototyping.","technologies":["IoT","AI","Prototyping"],"project_type":"IoT","year":"2025","featured":false,"github_url":"","demo_url":"","image_url":"/projects/p11.svg","impact":[]},{"id":"p01","title":"Traffic Sign Detection System","description":"Traffic-sign recognition project using deep learning and a Flask web interface. Includes image preprocessing, model experimentation and prediction display.","impact":[],"technologies":["Python","YOLOv8","MobileNet","ResNet","Flask","OpenCV"],"project_type":"AI/ML","year":"2025","featured":true,"github_url":"","demo_url":"","image_url":""},{"id":"p02","title":"Gemini Health AI Assistant","description":"Experimental wellness application integrating the Gemini API with a Streamlit interface to explore personalized health guidance.","impact":[],"technologies":["Python","Streamlit","Gemini API","Data Analysis"],"project_type":"AI/ML","year":"2024","featured":true,"github_url":"https://github.com/sufyan-github/Gemini-Health-App","demo_url":"","image_url":"/projects/p02.svg"},{"id":"p03","title":"Medical Chatbot (RAG)","description":"In-development medical question-answering project exploring retrieval-augmented generation with LangChain, embeddings and a vector store in a modular Python codebase.","impact":[],"technologies":["Python","LangChain","Pinecone","Flask","NLP"],"project_type":"AI/ML","year":"In development","featured":true,"github_url":"https://github.com/sufyan-github/end-to-end-medical-chatbot","demo_url":"","image_url":"/projects/p03.svg"},{"id":"p04","title":"FoodHub — Food Delivery Platform","description":"Full-stack food ordering project with authentication, order management and a provider dashboard, built with React, Node.js, Express and MongoDB.","impact":[],"technologies":["Node.js","Express","MongoDB","React","TailwindCSS"],"project_type":"Web Development","year":"2024","featured":true,"github_url":"https://github.com/sufyan-github/foodhub-complete-project","demo_url":"","image_url":"/projects/p04.svg"},{"id":"p05","title":"Vehicle Rental REST API","description":"Vehicle-rental backend project in Go with PostgreSQL, API documentation and authentication.","impact":[],"technologies":["Go","PostgreSQL","React","TailwindCSS","Swagger"],"project_type":"Web Development","year":"2024","featured":false,"github_url":"https://github.com/sufyan-github/go-api-vehicle_rental","demo_url":"","image_url":"/projects/p05.svg"},{"id":"p06","title":"EduBridge — Learning Platform","description":"Learning platform project using React and Laravel, with course enrolment, progress tracking and an admin interface.","impact":[],"technologies":["React","PHP","Laravel","MySQL","TailwindCSS"],"project_type":"Web Development","year":"2023","featured":false,"github_url":"https://github.com/sufyan-github/EduBridge","demo_url":"","image_url":"/projects/p06.svg"},{"id":"p12","title":"Verilog HDL & Processor Design","description":"Academic laboratory and project work: simulated combinational and sequential modules including multiplexers, registers, counters and finite-state machines. Explored instruction-set, datapath and control-unit design, comparing simulation waveforms with expected logic.","technologies":["Verilog","Digital Logic","Computer Architecture","Simulation"],"project_type":"Hardware","year":"Academic coursework","featured":false,"github_url":"","demo_url":"","image_url":"/projects/p12.svg","impact":[]}]$json$::jsonb, updated_at = now() WHERE content_key = 'projects';
